import type { ICoordinate } from "../interfaces/GameBoardInterface.ts";
import type { ILegalCoordinate } from "../interfaces/PlayerInterface.ts";
import type { IPredeterminedShip } from "../interfaces/ShipInterface.ts";
import Player from "../utils/Player.ts";
import Ship from "../utils/Ship.ts";
import { HORIZONTAL_NEXT_RANGE, VERTICAL_NEXT_RANGE } from "./nextRange.ts";

const PREDETERMINED_SHIP = () => {
  // Coordinate is row and col on two dimensional array, not x and y axis
  const ship: IPredeterminedShip[] = [
    {
      name: "Carrier",
      ship: Ship(5),
      coordinate: { start: [3, 3], end: [3, 7] },
      length: 5,
    },
    {
      name: "Battleship",
      ship: Ship(4),
      coordinate: { start: [6, 9], end: [9, 9] },
      length: 4,
    },
    {
      name: "Cruiser",
      ship: Ship(3),
      coordinate: { start: [8, 4], end: [8, 6] },
      length: 3,
    },
    {
      name: "Submarine",
      ship: Ship(3),
      coordinate: { start: [5, 2], end: [7, 2] },
      length: 3,
    },
    {
      name: "Destroyer",
      ship: Ship(2),
      coordinate: { start: [2, 7], end: [2, 8] },
      length: 2,
    },
  ];

  const randomizeShipCoordinate = () => {
    const getRandomCoordinate = Player().getRandomCoordinate;

    const startList: ICoordinate[] = [];
    const endList: ICoordinate[] = [];
    let allCoordinate: ICoordinate[] = [];

    return ship.map((individualShip) => {
      let isUnique = false;
      let currentStart;
      let currentEnd;

      while (!isUnique) {
        const randomStartCoordinate = getRandomCoordinate();
        const randomEndCoordinate = getRandomCoordinate();

        const startItem = destructIntoArray(randomStartCoordinate);
        const endItem = destructIntoArray(randomEndCoordinate);
        const rangeOfCoordinate = createRange(startItem, endItem);
        const nextRange = createNextRange({ start: startItem, end: endItem });

        if (
          !checkIfArrayContain(startList, startItem) &&
          !checkIfArrayContain(endList, endItem) &&
          isEitherHorizontalOrVertical(startItem, endItem) &&
          isEqualToShipSize(startItem, endItem, individualShip.length) &&
          rangeOfCoordinate.every(
            (item) => !checkIfArrayContain(allCoordinate, item),
          ) &&
          nextRange.every(
            (item) => !checkIfArrayContain(allCoordinate, item as ICoordinate),
          )
        ) {
          allCoordinate = [...allCoordinate, ...rangeOfCoordinate];
          startList.push(startItem);
          endList.push(endItem);

          currentStart = startItem;
          currentEnd = endItem;

          isUnique = true;
        }
      }

      return {
        ...individualShip,
        coordinate: {
          start: currentStart as unknown as ICoordinate,
          end: currentEnd as unknown as ICoordinate,
        },
      };
    });
  };

  const createRange = (start: ICoordinate, end: ICoordinate) => {
    const rangeOfCoordinate: ICoordinate[] = [];

    const isHorizontal = start[0] === end[0];

    const initialization = start[isHorizontal ? 1 : 0];
    const condition = end[isHorizontal ? 1 : 0];

    for (let i = initialization; i <= condition; i++) {
      const coordinateItem: ICoordinate = isHorizontal
        ? [start[0], i]
        : [i, start[1]];

      rangeOfCoordinate.push(coordinateItem);
    }

    return rangeOfCoordinate;
  };

  const checkIfArrayContain = (
    listArray: ICoordinate[],
    arrayItem: ICoordinate,
  ) => JSON.stringify(listArray).indexOf(JSON.stringify(arrayItem)) !== -1;

  const destructIntoArray = (coordinate: ILegalCoordinate): ICoordinate => [
    coordinate.x,
    coordinate.y,
  ];

  const isEitherHorizontalOrVertical = (
    currentStart: ICoordinate,
    currentEnd: ICoordinate,
  ) => {
    // It should be only horizontal or vertical positioned

    return (
      currentStart[0] === currentEnd[0] || currentStart[1] === currentEnd[1]
    );
  };

  const isEqualToShipSize = (
    currentStart: ICoordinate,
    currentEnd: ICoordinate,
    size: number,
  ) => {
    return (
      currentEnd[0] - currentStart[0] === size - 1 ||
      currentEnd[1] - currentStart[1] === size - 1
    );
  };

  const createNextRange = (
    currentPosition: IPredeterminedShip["coordinate"],
  ) => {
    const { start: positionStart, end: positionEnd } = currentPosition;

    const isHorizontal = positionStart[0] === positionEnd[0];

    if (isHorizontal) {
      return [
        ...HORIZONTAL_NEXT_RANGE.map((range) => {
          const { start, end } = range;

          const nextCoordinate = {
            start: [
              positionStart[0] + start[0],
              positionStart[1] + start[1],
            ] as ICoordinate,
            end: [
              positionEnd[0] + end[0],
              positionEnd[1] + end[1],
            ] as ICoordinate,
          };

          return createRange(nextCoordinate.start, nextCoordinate.end);
        }).flat(),
        [positionStart[0], positionStart[1] - 1],
        [positionEnd[0], positionEnd[1] + 1],
      ];
    }
    return [
      ...VERTICAL_NEXT_RANGE.map((range) => {
        const { start, end } = range;

        const nextCoordinate = {
          start: [
            positionStart[0] + start[0],
            positionStart[1] + start[1],
          ] as ICoordinate,
          end: [
            positionEnd[0] + end[0],
            positionEnd[1] + end[1],
          ] as ICoordinate,
        };

        return createRange(nextCoordinate.start, nextCoordinate.end);
      }).flat(),
      [positionStart[0] - 1, positionStart[1]],
      [positionEnd[0] + 1, positionEnd[1]],
    ];
  };

  return {
    ship,
    randomizeShipCoordinate,
    createRange,
    checkIfArrayContain,
    createNextRange,
  };
};

export default PREDETERMINED_SHIP;
